import { LoaderCircle } from "lucide-react";
import {
  Fragment,
  useRef,
  useState,
  type ChangeEvent,
  type CSSProperties,
  type InputHTMLAttributes,
  type KeyboardEvent,
  type ReactNode,
} from "react";
import { mergeClasses } from "./classes";
import {
  fieldHintClasses,
  fieldLabelClasses,
  fieldStatusMessages,
  getFieldStateColorClass,
  getFieldStatusIcon,
  roundedClasses,
  type FieldSize,
  type FieldStatus,
  type FieldVariant,
  type Rounded,
} from "./form";
import { Icon } from "./Icon";
import type { ThemeInput } from "./theme";
import {
  BalsaThemeContext,
  useControllableState,
  useResolvedThemeProps,
} from "./theme-context";
import type { SemanticColor } from "./types";

export type InputOTPMode = "numeric" | "alphanumeric";
export type InputOTPVariant = FieldVariant | "solid";

export interface InputOTPCellSlot {
  index: number;
  value: string;
  active: boolean;
}

export interface InputOTPProps extends Omit<
  InputHTMLAttributes<HTMLInputElement>,
  "value" | "defaultValue" | "onChange" | "size" | "color" | "children"
> {
  id: string;
  label: string;
  length?: number;
  mode?: InputOTPMode;
  fluid?: boolean;
  mask?: boolean;
  grouped?: boolean;
  separatorEvery?: number;
  separator?: string;
  size?: FieldSize;
  variant?: InputOTPVariant;
  color?: SemanticColor;
  rounded?: Rounded;
  hint?: string;
  loading?: boolean;
  status?: FieldStatus;
  statusMessage?: string;
  theme?: ThemeInput;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onComplete?: (value: string) => void;
  cell?: (slot: InputOTPCellSlot) => ReactNode;
}

const cellVariantClasses: Readonly<Record<InputOTPVariant, string>> = {
  outline: "bg-balsa-background",
  surface: "bg-balsa-input",
  soft: "",
  solid: "",
  glass: "backdrop-balsa",
};
const cellColorClasses: Readonly<Record<SemanticColor, Record<InputOTPVariant, string>>> = {
  primary: {
    outline: "border-balsa-primary text-balsa-primary",
    surface: "border-balsa-primary/30",
    soft: "border-transparent bg-balsa-primary/15 text-balsa-primary",
    solid: "border-balsa-primary bg-balsa-primary text-balsa-primary-foreground",
    glass: "border-balsa-primary/40 bg-balsa-primary/10 text-balsa-primary",
  },
  secondary: {
    outline: "border-balsa-secondary text-balsa-secondary",
    surface: "border-balsa-secondary/30",
    soft: "border-transparent bg-balsa-secondary/15 text-balsa-secondary",
    solid: "border-balsa-secondary bg-balsa-secondary text-balsa-secondary-foreground",
    glass: "border-balsa-secondary/40 bg-balsa-secondary/10 text-balsa-secondary",
  },
  accent: {
    outline: "border-balsa-accent text-balsa-accent",
    surface: "border-balsa-accent/30",
    soft: "border-transparent bg-balsa-accent/15 text-balsa-accent",
    solid: "border-balsa-accent bg-balsa-accent text-balsa-accent-foreground",
    glass: "border-balsa-accent/40 bg-balsa-accent/10 text-balsa-accent",
  },
  destructive: {
    outline: "border-balsa-destructive text-balsa-destructive",
    surface: "border-balsa-destructive/30",
    soft: "border-transparent bg-balsa-destructive/15 text-balsa-destructive",
    solid: "border-balsa-destructive bg-balsa-destructive text-balsa-destructive-foreground",
    glass: "border-balsa-destructive/40 bg-balsa-destructive/10 text-balsa-destructive",
  },
  success: {
    outline: "border-balsa-success text-balsa-success",
    surface: "border-balsa-success/30",
    soft: "border-transparent bg-balsa-success/15 text-balsa-success",
    solid: "border-balsa-success bg-balsa-success text-balsa-success-foreground",
    glass: "border-balsa-success/40 bg-balsa-success/10 text-balsa-success",
  },
  warning: {
    outline: "border-balsa-warning text-balsa-warning",
    surface: "border-balsa-warning/30",
    soft: "border-transparent bg-balsa-warning/15 text-balsa-warning",
    solid: "border-balsa-warning bg-balsa-warning text-balsa-warning-foreground",
    glass: "border-balsa-warning/40 bg-balsa-warning/10 text-balsa-warning",
  },
  info: {
    outline: "border-balsa-info text-balsa-info",
    surface: "border-balsa-info/30",
    soft: "border-transparent bg-balsa-info/15 text-balsa-info",
    solid: "border-balsa-info bg-balsa-info text-balsa-info-foreground",
    glass: "border-balsa-info/40 bg-balsa-info/10 text-balsa-info",
  },
};

export function InputOTP(rawProps: InputOTPProps) {
  const { props, theme } = useResolvedThemeProps("input-otp", "fields", rawProps, {
    size: "md",
    variant: "surface",
    rounded: "lg",
  } as const);
  const {
    id,
    label,
    length = 6,
    mode = "numeric",
    fluid = false,
    mask = false,
    grouped = false,
    separatorEvery = 0,
    separator = "–",
    size,
    variant,
    color = "primary",
    rounded,
    hint,
    disabled = false,
    loading = false,
    status = "default",
    statusMessage,
    required = false,
    name,
    autoComplete = "one-time-code",
    theme: _themeInput,
    value,
    defaultValue = "",
    onValueChange,
    onComplete,
    cell: renderCell,
    className,
    style,
    ...domProps
  } = props;
  void _themeInput;

  const [current, setValue] = useControllableState<string>({
    value,
    defaultValue,
    onChange: onValueChange,
  });
  const inputElement = useRef<HTMLInputElement | null>(null);
  const [focused, setFocused] = useState(false);
  const [caret, setCaret] = useState(0);

  const safeLength = Number.isFinite(length)
    ? Math.max(4, Math.min(10, Math.floor(length)))
    : 6;
  const safeSeparatorEvery = Number.isFinite(separatorEvery)
    ? Math.max(0, Math.floor(separatorEvery))
    : 0;
  const effectiveSeparatorEvery = safeSeparatorEvery > 0
    ? safeSeparatorEvery
    : grouped ? 3 : 0;

  function normalize(next: string): string {
    const filtered = mode === "numeric"
      ? next.replace(/\D/g, "")
      : next.replace(/[^a-z0-9]/gi, "");
    return filtered.slice(0, safeLength);
  }

  const displayed = normalize(current);
  const isDisabled = disabled || loading;
  const hintId = hint ? `${id}-hint` : undefined;
  const statusId = status === "unvalidated" ? `${id}-status` : undefined;
  const describedBy = [hintId, statusId].filter(Boolean).join(" ") || undefined;
  const effectiveStatusMessage = status === "unvalidated"
    ? statusMessage ?? fieldStatusMessages.unvalidated
    : undefined;
  const stateIcon = loading ? LoaderCircle : getFieldStatusIcon(status);
  const caretIndex = Math.min(caret, displayed.length);
  const activeIndex = Math.min(caretIndex, safeLength - 1);

  const groupClasses = mergeClasses(
    "relative flex max-w-full items-center gap-balsa-xs p-balsa-3xs",
    fluid ? "w-full" : "overflow-x-auto",
    isDisabled
      ? loading ? "cursor-progress" : "cursor-not-allowed"
      : "cursor-text",
    className,
  );
  const cellClasses = mergeClasses(
    "flex items-center justify-center font-balsa-body font-semibold tabular-nums transition-[border-color,box-shadow,opacity]",
    fluid ? "aspect-square min-w-0 flex-1" : "shrink-0",
    cellVariantClasses[variant],
    cellColorClasses[color][variant],
    fluid
      ? size === "sm" ? "text-base" : "text-lg"
      : size === "sm" ? "size-10 text-base" : "size-12 text-lg",
    roundedClasses[rounded],
    status === "validated"
      ? "border-balsa-success"
      : status === "unvalidated"
        ? "border-balsa-destructive"
        : "",
    isDisabled ? "bg-balsa-disabled text-balsa-disabled-foreground" : "",
  );
  const activeCellClasses = status === "unvalidated"
    ? "border-balsa-destructive ring-2 ring-balsa-destructive/30"
    : status === "validated"
      ? "border-balsa-success ring-2 ring-balsa-success/30"
      : "border-balsa-focus-ring ring-2 ring-balsa-focus-ring/30";
  const stateIconClasses = mergeClasses(
    "shrink-0",
    loading ? "animate-spin text-balsa-info" : getFieldStateColorClass(status),
  );

  const cells = Array.from({ length: safeLength }, (_, index) => ({
    index,
    value: displayed[index] ?? "",
    separatorAfter:
      effectiveSeparatorEvery > 0
      && (index + 1) % effectiveSeparatorEvery === 0
      && index < safeLength - 1,
  }));

  function handleInput(event: ChangeEvent<HTMLInputElement>): void {
    const next = normalize(event.currentTarget.value);
    setValue(next);
    setCaret(event.currentTarget.selectionStart ?? next.length);
    if (next.length === safeLength) onComplete?.(next);
  }

  function handleKeydown(event: KeyboardEvent<HTMLInputElement>): void {
    const input = inputElement.current;
    if (!input) return;
    if (event.key === "ArrowLeft" || event.key === "ArrowRight") {
      event.preventDefault();
      const direction = event.key === "ArrowLeft" ? -1 : 1;
      const next = Math.max(0, Math.min(displayed.length, caretIndex + direction));
      input.setSelectionRange(next, next);
      setCaret(next);
    }
  }

  function updateCaret(): void {
    setCaret(inputElement.current?.selectionStart ?? displayed.length);
  }

  return (
    <BalsaThemeContext.Provider value={theme}>
      <div
        data-balsa="input-otp"
        data-theme={theme.explicitPresentation?.id}
        data-theme-base={theme.explicitPresentation?.base}
        data-size={size}
        data-variant={variant}
        data-color={color}
        data-grouped={effectiveSeparatorEvery > 0 ? "true" : undefined}
        data-rounded={rounded}
        data-status={status}
        style={theme.explicitPresentation?.style as CSSProperties | undefined}
      >
        <label htmlFor={id} className={fieldLabelClasses}>
          {label}
          {required ? <span className="text-balsa-primary" aria-hidden="true">*</span> : null}
        </label>
        <div className={groupClasses} onClick={() => inputElement.current?.focus()}>
          <input
            {...domProps}
            ref={inputElement}
            id={id}
            data-balsa-control=""
            className="absolute inset-0 z-10 size-full cursor-inherit opacity-0"
            name={name}
            value={displayed}
            maxLength={safeLength}
            inputMode={mode === "numeric" ? "numeric" : "text"}
            pattern={mode === "numeric" ? "[0-9]*" : undefined}
            autoComplete={autoComplete}
            disabled={isDisabled}
            required={required}
            aria-busy={loading || undefined}
            aria-invalid={status === "unvalidated" || undefined}
            aria-describedby={describedBy}
            style={style}
            onChange={handleInput}
            onKeyDown={handleKeydown}
            onSelect={updateCaret}
            onFocus={() => {
              setFocused(true);
              updateCaret();
            }}
            onBlur={() => {
              setFocused(false);
            }}
          />
          {cells.map((entry) => {
            const active = focused && entry.index === activeIndex;
            const content = renderCell
              ? renderCell({ index: entry.index, value: entry.value, active })
              : mask && entry.value ? "•" : entry.value;
            return (
              <Fragment key={entry.index}>
                <span
                  data-balsa="input-otp-cell"
                  data-active={String(active)}
                  className={mergeClasses(cellClasses, active ? activeCellClasses : "")}
                  aria-hidden="true"
                >
                  {content}
                </span>
                {entry.separatorAfter ? (
                  <span className="shrink-0 text-balsa-muted-foreground" aria-hidden="true">
                    {separator}
                  </span>
                ) : null}
              </Fragment>
            );
          })}
          {stateIcon ? <Icon icon={stateIcon} size="md" className={stateIconClasses} /> : null}
        </div>
        {hint ? <span id={hintId} className={fieldHintClasses}>{hint}</span> : null}
        {effectiveStatusMessage ? (
          <span
            id={statusId}
            role="alert"
            className="mt-balsa-xs block text-sm font-medium text-balsa-destructive"
          >
            {effectiveStatusMessage}
          </span>
        ) : null}
      </div>
    </BalsaThemeContext.Provider>
  );
}

import { extendTailwindMerge, type ClassNameValue } from "tailwind-merge";

/**
 * Every custom scale has to be declared here, not only defined in CSS.
 *
 * tailwind-merge decides which of two classes wins by knowing they belong to
 * the same group. A scale it has not been told about is not a group, so a
 * component's own `gap-balsa-md` and a caller's `gap-3` both survive the merge
 * and whichever CSS rule happens to come last decides — the caller's override
 * silently stops working. That is what happened the moment the spacing scale
 * landed, and it is invisible in the source: the class list looks right.
 */
const twMerge = extendTailwindMerge({
  extend: {
    theme: {
      radius: ["balsa-control", "balsa-surface", "balsa-panel"],
      text: [
        "balsa-2xs",
        "balsa-xs",
        "balsa-sm",
        "balsa-base",
        "balsa-prose",
        "balsa-lg",
        "balsa-xl",
        "balsa-2xl",
        "balsa-3xl",
        "balsa-4xl",
        "balsa-5xl",
        "balsa-6xl",
      ],
      leading: ["balsa-tight", "balsa-snug", "balsa-normal", "balsa-relaxed", "balsa-prose"],
      tracking: ["balsa-title", "balsa-normal", "balsa-label"],
      shadow: [
        "balsa-control",
        "balsa-surface",
        "balsa-panel",
        "balsa-sm",
        "balsa-md",
        "balsa-lg",
        "balsa-detail",
      ],
      spacing: [
        "balsa-4xs",
        "balsa-3xs",
        "balsa-2xs",
        "balsa-xs",
        "balsa-sm",
        "balsa-md",
        "balsa-lg",
        "balsa-xl",
        "balsa-2xl",
        "balsa-3xl",
        "balsa-section-sm",
        "balsa-section-md",
        "balsa-section-lg",
        "balsa-control-inline",
        "balsa-density-compact",
        "balsa-density-default",
        "balsa-density-comfortable",
      ],
    },
    classGroups: {
      // `backdrop-balsa` is a custom utility rather than a value on a scale, so
      // it has to join the group it competes with by name. Without this a
      // caller's `backdrop-blur-none` and the component's `backdrop-balsa` both
      // survive the merge and CSS order decides which blur wins — the same
      // failure the spacing scale hit the moment it landed.
      "backdrop-blur": ["backdrop-balsa", "backdrop-balsa-overlay"],
    },
  },
});

export function mergeClasses(...inputs: unknown[]): string {
  return twMerge(...(inputs as ClassNameValue[]));
}

export function withoutClassAttribute(
  attrs: Readonly<Record<string, unknown>>,
): Record<string, unknown> {
  return Object.fromEntries(
    Object.entries(attrs).filter(([name]) => name !== "class"),
  );
}

import { CircleAlert, CircleCheckBig } from "lucide-react";
import type { IconComponent } from "./Icon";

export const fieldLabelClasses =
  "mb-balsa-2xs block text-sm font-medium leading-snug text-balsa-foreground";

export const fieldHintClasses = "mt-balsa-2xs block text-sm text-balsa-muted-foreground";

export const textControlClasses =
  "w-full rounded-lg border font-balsa-body text-balsa-input-foreground outline-none transition-[border-color,box-shadow,opacity] placeholder:text-balsa-muted-foreground focus:border-balsa-focus-ring focus:ring-2 focus:ring-balsa-focus-ring/30 disabled:border-balsa-border disabled:bg-balsa-disabled disabled:text-balsa-disabled-foreground";

export const textControlPopupClasses =
  "max-h-64 overflow-auto rounded-lg p-balsa-3xs text-balsa-surface-elevated-foreground shadow-balsa-surface transition-[opacity,transform,visibility] duration-balsa-fast ease-balsa";

export const textControlOptionClasses =
  "flex min-h-8 w-full items-center justify-between rounded-md px-balsa-sm py-balsa-2xs text-left text-sm transition-colors";

/*
 * No bare `border`. Tailwind compiles it to a literal 1px, which outranks the
 * `border-width: var(--balsa-border-width)` the stylesheet sets on these
 * controls -- so a checkbox and a radio kept a 1px edge at every border
 * setting while everything around them moved. The colour utilities stay; only
 * the width comes from the token.
 */
export const choiceInputClasses =
  "shrink-0 cursor-pointer appearance-none outline-none transition-[border-color,background-color,box-shadow,opacity] focus-visible:border-balsa-focus-ring focus-visible:ring-2 focus-visible:ring-balsa-focus-ring/30 disabled:cursor-not-allowed disabled:border-balsa-border disabled:bg-balsa-disabled";

export type FieldStatus = "default" | "validated" | "unvalidated";
export type FieldSize = "sm" | "md";
export type FieldVariant = "outline" | "surface" | "soft" | "glass";
export type Rounded = "none" | "sm" | "md" | "lg" | "xl" | "2xl" | "3xl" | "full";
export type TextareaResize = "none" | "vertical" | "both";

export const roundedClasses: Readonly<Record<Rounded, string>> = {
  none: "rounded-none",
  sm: "rounded-sm",
  md: "rounded-md",
  lg: "rounded-lg",
  xl: "rounded-xl",
  "2xl": "rounded-2xl",
  "3xl": "rounded-3xl",
  full: "rounded-full",
};

/**
 * A surface that may be contained by another one.
 *
 * `auto` means "concentric with whatever contains me": the corner follows the
 * containing surface's radius minus the inset between them, so the gap between
 * the two edges stays even instead of thickening at every corner. A surface
 * standing on its own finds nothing published to nest inside and keeps the
 * ordinary surface radius.
 *
 * Kept apart from `Rounded` because that union is shared with text controls,
 * where there is nothing to be concentric with and `auto` would be a value
 * nobody could act on.
 */
export type SurfaceRounded = Rounded | "auto";

export const surfaceRoundedClasses: Readonly<Record<SurfaceRounded, string>> = {
  ...roundedClasses,
  // Deliberately no class. The radius comes from the concentric rule in
  // balsa-theme.css, keyed on data-rounded="auto"; a utility emitted here would
  // outrank it and pin the corner to one value.
  auto: "",
};

const fieldVariantClasses: Readonly<Record<FieldVariant, string>> = {
  outline: "border-balsa-input-border bg-balsa-background",
  surface: "border-balsa-input-border bg-balsa-input",
  soft: "border-transparent bg-balsa-muted",
  glass: "border-balsa-border/70 bg-balsa-surface/70 backdrop-balsa",
};

const fieldPopupVariantClasses: Readonly<Record<FieldVariant, string>> = {
  outline: "border-balsa-input-border bg-balsa-background",
  surface: "border-balsa-border-strong bg-balsa-surface-elevated",
  soft: "border-transparent bg-balsa-muted",
  glass: "border-balsa-border/70 bg-balsa-surface/80 backdrop-balsa",
};

export interface AnchoredPopupPosition {
  left: number;
  top: number;
  width: number;
}

const textControlSizeClasses: Record<FieldSize, string[]> = {
  sm: ["h-8", "px-balsa-md", "text-sm"],
  md: ["h-9", "px-balsa-md", "text-sm"],
};

const textareaResizeClasses: Readonly<Record<TextareaResize, string>> = {
  none: "resize-none",
  vertical: "resize-y",
  both: "resize",
};

export const fieldStatusMessages: Record<
  Extract<FieldStatus, "unvalidated">,
  string
> = {
  unvalidated: "Check this information and try again.",
};

export function getTextControlClasses(
  status: FieldStatus,
  hasAdornment: boolean,
  disabled: boolean,
  loading: boolean,
  size: FieldSize = "md",
  rounded: Rounded = "lg",
  variant: FieldVariant = "surface",
): string[] {
  const resolvedSize = textControlSizeClasses[size] ? size : "md";
  return [
    textControlClasses,
    fieldVariantClasses[variant],
    roundedClasses[rounded],
    ...textControlSizeClasses[resolvedSize],
    ...(loading
      ? ["disabled:cursor-progress"]
      : disabled
        ? ["disabled:cursor-not-allowed"]
        : ["cursor-pointer"]),
    ...(status === "validated" ? ["border-balsa-success", "focus:border-balsa-success"] : []),
    ...(status === "unvalidated"
      ? ["border-balsa-destructive", "focus:border-balsa-destructive", "focus:ring-balsa-destructive/30"]
      : []),
    ...(hasAdornment ? ["pr-10"] : []),
  ];
}

export function getTextControlPopupClasses(
  rounded: Rounded = "lg",
  variant: FieldVariant = "surface",
): string[] {
  return [textControlPopupClasses, roundedClasses[rounded], fieldPopupVariantClasses[variant]];
}

export function getTextareaControlClasses(
  status: FieldStatus,
  disabled: boolean,
  loading: boolean,
  size: FieldSize = "md",
  rounded: Rounded = "lg",
  resizable: TextareaResize = "vertical",
  hasAdornment = false,
  variant: FieldVariant = "surface",
): string[] {
  return [
    textControlClasses,
    fieldVariantClasses[variant],
    "h-auto min-h-0 py-balsa-xs leading-6",
    roundedClasses[rounded],
    textareaResizeClasses[resizable],
    size === "sm" ? "px-balsa-md text-sm leading-5" : "px-balsa-md text-sm leading-6",
    ...(loading
      ? ["disabled:cursor-progress"]
      : disabled
        ? ["disabled:cursor-not-allowed"]
        : ["cursor-text"]),
    ...(status === "validated" ? ["border-balsa-success", "focus:border-balsa-success"] : []),
    ...(status === "unvalidated"
      ? ["border-balsa-destructive", "focus:border-balsa-destructive", "focus:ring-balsa-destructive/30"]
      : []),
    ...(hasAdornment ? ["pr-10"] : []),
  ];
}

export function getChoiceInputClasses(variant: FieldVariant = "surface"): string[] {
  return [choiceInputClasses, fieldVariantClasses[variant]];
}

export function getChoiceTrackClasses(variant: FieldVariant = "surface"): string {
  return fieldVariantClasses[variant];
}

export function getAnchoredPopupPosition(
  trigger: HTMLElement,
  popup: HTMLElement,
  fallbackHeight = 256,
): AnchoredPopupPosition {
  const triggerRect = trigger.getBoundingClientRect();
  const popupRect = popup.getBoundingClientRect();
  const viewportPadding = 8;
  const gap = 8;
  const width = Math.min(
    triggerRect.width,
    window.innerWidth - viewportPadding * 2,
  );
  const height = popupRect.height || fallbackHeight;
  const maxLeft = Math.max(
    viewportPadding,
    window.innerWidth - width - viewportPadding,
  );

  return {
    width,
    left: Math.min(Math.max(triggerRect.left, viewportPadding), maxLeft),
    top:
      triggerRect.bottom + gap + height <= window.innerHeight - viewportPadding
        ? triggerRect.bottom + gap
        : Math.max(viewportPadding, triggerRect.top - height - gap),
  };
}

export function getFieldStatusIcon(status: FieldStatus): IconComponent | undefined {
  if (status === "validated") return CircleCheckBig;
  if (status === "unvalidated") return CircleAlert;
  return undefined;
}

export function getFieldStateColorClass(status: FieldStatus): string {
  if (status === "unvalidated") return "text-balsa-destructive";
  if (status === "validated") return "text-balsa-success";
  return "text-balsa-muted-foreground";
}

export type ActionColor = "neutral" | "primary" | "secondary" | "accent" | "destructive";
export type StatusColor = "success" | "warning" | "info";
/**
 * Status surfaces communicate state, so they exclude neutral: an action can
 * legitimately carry no emphasis, but a status that means nothing is not a status.
 */
export type SemanticColor = Exclude<ActionColor, "neutral"> | StatusColor;
export type Rounded = "none" | "sm" | "md" | "lg" | "xl" | "2xl" | "3xl" | "full";
export type CardVariant = "surface" | "elevated" | "muted" | "outline" | "soft" | "glass";
export type CardColor = ActionColor;
export type CardPadding = "none" | "sm" | "md" | "lg";
export type CardSize = Exclude<CardPadding, "none">;

interface ActionColorClassSet {
  solid: string[];
  soft: string[];
  outline: string[];
  glass: string[];
  text: string[];
}

interface SemanticColorClassSet {
  solid: string[];
  soft: string[];
  outline: string[];
  glass: string[];
}

export const actionColorClasses: Readonly<Record<ActionColor, ActionColorClassSet>> = {
  // Chrome that should not compete with the content it frames: a filled neutral
  // action uses the inverse pair, and every quieter treatment resolves to the
  // plain foreground rather than a palette accent.
